"use client";
import * as React from "react";
import { Eye, EyeOff, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { KalosFieldMessage } from "@/components/ui/kalos-field-message";
import { controlStyles } from "@/components/ui/kalos-styles";
import { InputGroup, InputGroupInput, InputGroupAddon, InputGroupButton } from "@/components/ui/kalos-aria-input-group";
import { Field, FieldLabel } from "@/components/ui/kalos-aria-field";

export function KalosInput({ label, hint, error, id, type, clearable = true, onClear, value, defaultValue, onChange, ref, className, ...props }: React.ComponentProps<"input"> & {
  label: string;
  hint?: string;
  error?: string;
  clearable?: boolean;
  onClear?: () => void;
}) {
  const autoId = React.useId();
  const fieldId = id || autoId;
  const descriptionId = `${fieldId}-description`;
  const inputRef = React.useRef<HTMLInputElement>(null);
  const [revealed, setRevealed] = React.useState(false);
  const [internalValue, setInternalValue] = React.useState(defaultValue ?? "");
  const hasValue = String(value ?? internalValue).length > 0;
  const showClear = type !== "password" && clearable && hasValue && !props.disabled && !props.readOnly;
  React.useEffect(() => {
    const form = inputRef.current?.form;
    if (!form) return;
    const reset = (event: Event) => queueMicrotask(() => {
      if (event.defaultPrevented) return;
      setInternalValue(defaultValue ?? "");
      setRevealed(false);
    });
    form.addEventListener("reset", reset);
    return () => form.removeEventListener("reset", reset);
  }, [defaultValue]);
  function clear() {
    const input = inputRef.current;
    if (!input || props.disabled || props.readOnly) return;
    Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")?.set?.call(input, "");
    input.dispatchEvent(new Event("input", { bubbles: true }));
    setInternalValue("");
    onClear?.();
    input.focus();
  }
  return (
    <Field data-invalid={!!error} data-disabled={props.disabled || undefined} className="gap-1.5">
      <FieldLabel htmlFor={fieldId} className={controlStyles.label}>{label}{props.required ? <span aria-hidden="true" className={controlStyles.requiredMark}>*</span> : null}</FieldLabel>
      <InputGroup data-invalid={!!error} data-disabled={props.disabled || undefined} className={controlStyles.inputGroup}>
        <InputGroupInput {...props} id={fieldId} type={type === "password" && revealed ? "text" : type} value={value} defaultValue={defaultValue}
          ref={element => { inputRef.current = element; if (typeof ref === "function") ref(element); else if (ref) ref.current = element; }}
          className={cn(controlStyles.inputContent, className)} aria-invalid={!!error} aria-describedby={error || hint ? descriptionId : undefined}
          onChange={event => { setInternalValue(event.target.value); onChange?.(event); }}
          onKeyDown={event => { props.onKeyDown?.(event); if (event.key === "Escape" && showClear && !event.defaultPrevented) { event.preventDefault(); clear(); } }}
        />
        {showClear || type === "password" ? <InputGroupAddon align="inline-end" className={controlStyles.inputAddon}>
          {showClear ? <InputGroupButton className={cn(controlStyles.inputAction, controlStyles.inputClear)} aria-label={`清空${label}`} aria-controls={fieldId} onClick={clear}><X aria-hidden="true" /></InputGroupButton> : null}
          {type === "password" ? <InputGroupButton className={controlStyles.inputAction} isDisabled={props.disabled} aria-label={revealed ? "隐藏密码" : "显示密码"} aria-pressed={revealed} aria-controls={fieldId} onClick={() => { setRevealed(current => !current); inputRef.current?.focus(); }}>{revealed ? <EyeOff aria-hidden="true" /> : <Eye aria-hidden="true" />}</InputGroupButton> : null}
        </InputGroupAddon> : null}
      </InputGroup>
      <KalosFieldMessage id={descriptionId} error={error} hint={hint} />
    </Field>
  );
}

"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import { Group, type GroupProps } from "react-aria-components";

import { Button } from "@/components/ui/kalos-aria-button";
import { Input } from "@/components/ui/kalos-aria-input";
import { Textarea } from "@/components/ui/kalos-aria-textarea";

function InputGroup({ className, ...props }: GroupProps) {
  return (
    <Group
      data-slot="input-group"
      className={cn(
        "group/input-group relative flex h-8 w-full min-w-0 items-center rounded-lg border border-input transition-colors outline-none in-data-[slot=combobox-content]:focus-within:border-inherit in-data-[slot=combobox-content]:focus-within:ring-0 has-disabled:bg-input/50 has-disabled:opacity-50 has-[[data-slot][aria-invalid=true]]:border-destructive has-[[data-slot][aria-invalid=true]]:ring-3 has-[[data-slot][aria-invalid=true]]:ring-destructive/20 has-[>[data-align=block-end]]:h-auto has-[>[data-align=block-end]]:flex-col has-[>[data-align=block-start]]:h-auto has-[>[data-align=block-start]]:flex-col has-[>textarea]:h-auto dark:bg-input/30 dark:has-disabled:bg-input/80 dark:has-[[data-slot][aria-invalid=true]]:ring-destructive/40 has-[>[data-align=block-end]]:[&>input]:pt-3 has-[>[data-align=block-start]]:[&>input]:pb-3 has-[>[data-align=inline-end]]:[&>input]:pr-1.5 has-[>[data-align=inline-start]]:[&>input]:pl-1.5",
        className,
      )}
      {...props}
    />
  );
}

const inputGroupAddonVariants = cva(
  "flex h-auto cursor-text items-center justify-center gap-2 py-1.5 text-[13px] font-medium text-muted-foreground select-none group-data-[disabled=true]/input-group:opacity-50 [&>kbd]:rounded-[calc(var(--radius)-5px)] [&>svg:not([class*='size-'])]:size-4",
  {
    variants: {
      align: {
        "inline-start":
          "order-first pl-2 has-[>button]:ml-[-0.3rem] has-[>kbd]:ml-[-0.15rem]",
        "inline-end":
          "order-last pr-2 has-[>button]:mr-[-0.3rem] has-[>kbd]:mr-[-0.15rem]",
        "block-start":
          "order-first w-full justify-start px-2.5 pt-2 group-has-[>input]/input-group:pt-2 [.border-b]:pb-2",
        "block-end":
          "order-last w-full justify-start px-2.5 pb-2 group-has-[>input]/input-group:pb-2 [.border-t]:pt-2",
      },
    },
    defaultVariants: {
      align: "inline-start",
    },
  },
);

function InputGroupAddon({
  className,
  align = "inline-start",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof inputGroupAddonVariants>) {
  return (
    <div
      role="group"
